    type="FUNCTION",
    input_parameters={
        "city": "Zürich",
        "party_size": 2
    }
), ToolCall(
    name="book_table",
    type="MCP",
    input_parameters={
        "day": "Saturday",
        "restaurant": "Café Odéon"
    },
    output='Booked for Saturday at 19:00'
), ToolCall(
    name="send_newsletter",
    type="FUNCTION"
)]

